INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1281517-me412', 'stk-user5272', 'ME 412', 'info', '{"desc": "القسم الثاني من مشروع التخرج (me411 . Me 412)\n\nيعتمد اعتماد كلي على الدكتور اللي تختاره وفكرة المشروع\n\nما يكون في كلاسات ، في العادة يكون فيه ميتنق كل اسبوع مع الدكتور المسؤول\n\nآخر الترم فيه ريبورت وبرزنتيشن عليها أسئلة من لجنة التقييم\n\nلو فكرة المشروع معقدة او صعبة بيكون فيه تعب ، والعكس\nوكذلك الدكتور", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-412-senior-design-project-ii/120750/2", "user": "user5272", "ts": 1383405034000, "tid": 120750, "pn": 2}}', 1383405034000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-me412', 'stk-khdsa2022', 'ME 412', 'doc', '{"docs": [{"id": "stk-dr-f118647", "n": "Dr. Bilal Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : Bilal al qureshi\nBY WHATSAPP\nالمادة: ME 412-ME411\nالفصل الدراسي: 182-191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : اجتماع ، كل اسبوع تقريبا هذا بالنسبة لاول سمستر ، اما بالنسبة للثاني كان اجتماع على حسب الضرورة\nطريقة الشرح : طبعاً أخذنا مع الدكتور موضوع كان مادرسناه ، وبطبيعة الحال ، كان يوجهنا وين نقرا وين نبحث من دون ان يعطينا اي معلومة . كان يقول ان هالطريقة مؤلمة في التعلم لكنها فعالة جداً .\nالكويزات : -- مافيها كويزات --\nالمياجر: -- مافيها مياجر --\nالفاينلات : بالنسبة للمشروع ، انت لازم تلاحق روحك ، لازم تتعلم بسرعة وتفهم بسرعة ولا تأجل ، لان كل شي راح يتراكم عليك . الدكتور كان متساعد جدا في القريدات ، لكن لاتتوقع اذا تأخرت في كتابة واستنباط المعاملات ، بيجي الدكتور ويقولك ترى تأخرت لازم تخلص بسرعة . لان هذي مسؤوليتك . الدكتور دائما يحفزك اذا جيت مكتبه ، ويخليك تحس انك انسان عظيم كمهندس ميانيكي\nالقريد النهائي: A\nالصوت: واضح بما ان الاجتماع في مكتبه .\nإضافات :المفروض مشروع التخرج يتقسم بهالشكل :\nالسمستر الاول فهم خلفية المشروع ، واستنباط النموذج الرياضي للمشروع ( mathematical module ) وكتابة برنامج يحل النموذج الرياضي .\n\nالسمستر الثاني : مرحلة تصنيع المشروع ، من قص خشب وحديد وتلحيم وتلزيق وهلمجال .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518859-me412", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bilal-qureshi/118647/9", "user": "Khdsa2022", "ts": 1578312986000, "tid": 118647, "pn": 9}}]}', 1578312986000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
